-- Partial: only orders that are not finished yet
CREATE INDEX idx_orders_pending ON orders (created_at) WHERE status = 'PENDING';

-- Covering: no trip to the table to read the total
CREATE INDEX idx_orders_customer ON orders (customer_id) INCLUDE (total);

-- GIN for JSONB queries
CREATE INDEX idx_products_attributes ON products USING GIN (attributes);

-- WRONG: 95% of the rows are active
CREATE INDEX idx_users_active ON users (active);

-- RIGHT: index only the rare case you query
CREATE INDEX idx_users_inactive ON users (id) WHERE active = false;

Level              Dirty read   Non-repeatable read   Phantom / write skew
READ COMMITTED     no           yes                   yes
REPEATABLE READ    no           no                    write skew possible (PostgreSQL)
SERIALIZABLE       no           no                    no (may fail with retry)

BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM shifts WHERE shift = '2024-05-10-night';
INSERT INTO shifts (doctor_id, shift) VALUES (7, '2024-05-10-night');
COMMIT;
-- On conflict: ERROR: could not serialize access ... -> the application retries

// WRONG: the failure goes straight to the user
@Transactional(isolation = Isolation.SERIALIZABLE)
public void bookShift(Long doctorId, String shift) { ... }
// "could not serialize access due to read/write dependencies" -> HTTP 500

// RIGHT: retry the whole transaction (a few attempts, with backoff)
// on serialization failures (SQLSTATE 40001) — never inside the failed transaction

// Transfer: always lock accounts in the same order
@Transactional
public void transfer(Long fromId, Long toId, BigDecimal amount) {
    Long first = Math.min(fromId, toId);
    Long second = Math.max(fromId, toId);
    Account a = accounts.findForUpdate(first).orElseThrow();
    Account b = accounts.findForUpdate(second).orElseThrow();
    // debit and credit...
}

// WRONG
try { accounts.debit(a); } catch (DeadlockLoserDataAccessException e) { /* ignore */ }
accounts.credit(b);
// ERROR: current transaction is aborted, commands ignored until end of transaction block

// RIGHT: let the transaction fail, then run the whole method again (a few attempts)

-- Range partitioning by date (PostgreSQL)
CREATE TABLE events (
  id         BIGSERIAL,
  created_at TIMESTAMP NOT NULL,
  payload    JSONB
) PARTITION BY RANGE (created_at);

CREATE TABLE events_2024_05 PARTITION OF events
  FOR VALUES FROM ('2024-05-01') TO ('2024-06-01');

-- WRONG: no created_at filter -> every partition is scanned
SELECT * FROM events WHERE payload->>'orderId' = '42';

-- RIGHT: include the partition key so only one partition is read
SELECT * FROM events
WHERE created_at >= '2024-05-01' AND created_at < '2024-06-01'
  AND payload->>'orderId' = '42';

// MongoDB: confirmed by a majority, so it survives a primary failover
db.payments.insertOne(
  { orderId: 42, status: "CONFIRMED" },
  { writeConcern: { w: "majority" } }
)
db.payments.find({ orderId: 42 }).readConcern("majority")

-- Cassandra (cqlsh): read and write on a majority of replicas
CONSISTENCY QUORUM;
SELECT * FROM payments WHERE order_id = 42;

// WRONG: right after confirming the payment
db.payments.find({ orderId: 42 }).readPref("secondary")   // may still show PENDING

// RIGHT for data the user just changed
db.payments.find({ orderId: 42 }).readPref("primary")

BEGIN;
INSERT INTO orders (id, customer_id, total, status) VALUES (123, 7, 104.80, 'CREATED');
INSERT INTO outbox (id, aggregate, type, payload)
  VALUES (gen_random_uuid(), 'order-123', 'OrderCreated', '{"orderId":123,"total":104.80}');
COMMIT;
-- A publisher reads the outbox, sends to Kafka and marks the row as published

// WRONG: runs twice for a redelivered event
void onOrderCreated(OrderCreated e) { stock.reserve(e.items()); }

// RIGHT: INSERT into processed_events (UNIQUE event_id) in the same transaction
@Transactional
void onOrderCreated(OrderCreated e) {
    if (!processed.register(e.eventId())) return;   // already handled
    stock.reserve(e.items());
}
